    readonly 'integrationsCatalog.entry.mongodb.details': 'Install MongoDB so the agent can inspect collections and indexes and run read-only queries against your cluster. Comes with MongoDB skills for natural-language queries, query optimization and schema design.';
    readonly 'integrationsCatalog.entry.mcp-toolbox.details': 'Install MCP Toolbox so the agent gets ready-made, permission-aware tools for your Postgres, MySQL or SQL Server database.';
    readonly 'integrationsCatalog.entry.grafana.details': 'Install Grafana so the agent can query dashboards and panels and find the datasources behind an alert.';
    readonly 'integrationsCatalog.entry.terraform.details': 'Install Terraform so the agent can look up providers and modules in the registry and read the docs it needs to write correct configuration. Comes with HashiCorp skills for the Terraform style guide and Terraform tests.';
    readonly 'integrationsCatalog.entry.snyk.details': 'Install Snyk so the agent can scan your projects for vulnerabilities and license issues and suggest fixes.';
